#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")" && pwd)"
cd "$ROOT"
PORT="${PORT:-3000}"
OUTPUT_DIR="${OPENCODE_WEB_DIR:-/home/runner/work/_temp/omgithub-web}"
mkdir -p "$OUTPUT_DIR/site"
printf '{"project":"%s","directory":"%s"}\n' "$ROOT" "$OUTPUT_DIR/site" > "$OUTPUT_DIR/deployment-output.json"

cat > "$OUTPUT_DIR/site/index.html" <<'HTML'
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daymark — Your day, in focus</title><style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap');
:root{font-family:'DM Sans',sans-serif;color:#242b28;background:#f5f6f2;font-synthesis:none}*{box-sizing:border-box}body{margin:0}.shell{max-width:1180px;margin:auto;padding:30px 34px}.top{display:flex;justify-content:space-between;align-items:center}.brand{font:800 23px Manrope;letter-spacing:-1px}.brand i{color:#6e8f68;font-style:normal}.date{color:#78817a;font-size:13px}.layout{display:grid;grid-template-columns:235px 1fr;gap:52px;margin-top:54px}.side{border-right:1px solid #e4e7e0;padding-right:26px}.profile{display:flex;align-items:center;gap:12px;margin:0 0 35px}.avatar{width:42px;height:42px;border-radius:50%;background:#e7eada;display:grid;place-items:center;color:#61785a;font-weight:700}.profile b{display:block;font-size:14px}.profile small{color:#929992;font-size:12px}.nav{display:grid;gap:8px}.nav button{border:0;background:none;text-align:left;padding:12px;border-radius:9px;color:#707a72;font:500 14px 'DM Sans';cursor:pointer}.nav button.active{background:#e9eee5;color:#4f704c;font-weight:700}.nav span{float:right;color:#a0a79f}.quote{margin-top:80px;padding:17px;background:#eeefe9;border-radius:12px;color:#727a71;font-size:12px;line-height:1.65}.quote b{display:block;color:#5d7758;font-size:11px;margin-bottom:8px;text-transform:uppercase;letter-spacing:1px}.content{max-width:760px}.eyebrow{font-size:12px;color:#71846a;font-weight:700;letter-spacing:1.4px;text-transform:uppercase}.heading{font:700 34px Manrope;letter-spacing:-1.2px;margin:8px 0 6px}.sub{font-size:14px;color:#89918a}.progress{margin:27px 0 30px;padding:17px 20px;background:#fff;border:1px solid #eceee8;border-radius:12px;display:flex;align-items:center;gap:15px}.ring{width:42px;height:42px;border-radius:50%;background:conic-gradient(#78916e 0 63%,#edf0e9 63%);display:grid;place-items:center}.ring:after{content:'5';display:grid;place-items:center;background:#fff;width:31px;height:31px;border-radius:50%;font-size:12px;font-weight:700}.progress strong{font-size:13px}.progress small{display:block;color:#929a92;margin-top:4px;font-size:12px}.progress .percent{margin-left:auto;color:#71866b;font-size:13px;font-weight:700}.section-title{font:700 16px Manrope;margin:25px 0 13px;display:flex;justify-content:space-between}.section-title small{font:500 12px 'DM Sans';color:#9aa199}.task{display:flex;align-items:center;gap:14px;padding:16px 17px;background:#fff;border:1px solid #eceee8;border-radius:10px;margin-bottom:9px;transition:.2s}.task.done{opacity:.58}.check{width:19px;height:19px;border:1.5px solid #cdd4c9;border-radius:6px;flex:none;cursor:pointer}.done .check{background:#78916e;border-color:#78916e;position:relative}.done .check:after{content:'✓';color:white;position:absolute;font-size:13px;left:3px;top:-1px}.taskcopy{flex:1}.taskcopy b{font-size:13px;font-weight:600}.done .taskcopy b{text-decoration:line-through}.taskcopy small{display:block;color:#9ba29b;font-size:11px;margin-top:5px}.tag{padding:5px 8px;border-radius:5px;background:#f5eee4;color:#aa8350;font-size:10px;font-weight:700}.tag.green{color:#6c8865;background:#eef3e9}.add{width:100%;border:1px dashed #d8ded5;background:transparent;border-radius:9px;padding:13px;color:#818a81;text-align:left;font:500 13px 'DM Sans';cursor:pointer}.add:hover{background:#fff}.mobile-nav{display:none}
@media(max-width:700px){.shell{padding:21px 19px 90px}.top{align-items:flex-start}.date{font-size:11px;margin-top:7px}.layout{display:block;margin-top:37px}.side{display:none}.heading{font-size:29px}.sub{line-height:1.5}.progress{margin:23px 0}.task{padding:14px 12px;gap:10px}.tag{font-size:9px;padding:5px 6px}.mobile-nav{display:flex;position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid #e9ece6;justify-content:space-around;padding:13px 8px calc(13px + env(safe-area-inset-bottom));font-size:10px;color:#889088}.mobile-nav b{color:#587653}.section-title{margin-top:22px}}
</style></head><body><div class="shell"><header class="top"><div class="brand">daymark<i>.</i></div><div class="date" id="date"></div></header><div class="layout"><aside class="side"><div class="profile"><div class="avatar">A</div><div><b>Alex Morgan</b><small>Personal workspace</small></div></div><nav class="nav"><button class="active">◷ &nbsp; My day <span>8</span></button><button>▣ &nbsp; Upcoming</button><button>⌑ &nbsp; Completed</button></nav><div class="quote"><b>A little reminder</b>“You don’t have to see the whole staircase, just take the first step.”</div></aside><main class="content"><div class="eyebrow">Wednesday, September 23</div><h1 class="heading">Good morning, Alex <span>✳</span></h1><p class="sub">A fresh day is a fresh start. Here’s what’s on your mind.</p><div class="progress"><div class="ring"></div><div><strong>You're finding your rhythm</strong><small><span id="count">5</span> of 8 tasks completed today</small></div><div class="percent" id="percent">63%</div></div><div class="section-title">Today <small>◷ &nbsp; 3 tasks left</small></div><div id="tasks"><div class="task done"><div class="check"></div><div class="taskcopy"><b>Review project proposal</b><small>◷ &nbsp; 9:00 AM · Work</small></div><span class="tag green">FOCUS</span></div><div class="task done"><div class="check"></div><div class="taskcopy"><b>Morning pages & coffee</b><small>◷ &nbsp; 9:30 AM · Personal</small></div></div><div class="task"><div class="check"></div><div class="taskcopy"><b>Send the updated designs to Maya</b><small>◷ &nbsp; 11:00 AM · Work</small></div><span class="tag">PRIORITY</span></div><div class="task"><div class="check"></div><div class="taskcopy"><b>Pick up groceries for dinner</b><small>◷ &nbsp; 4:30 PM · Errands</small></div></div><div class="task"><div class="check"></div><div class="taskcopy"><b>Take a real lunch break</b><small>◷ &nbsp; 12:30 PM · Personal</small></div><span class="tag green">SELF CARE</span></div></div><div class="section-title">Later <small>5 tasks</small></div><button class="add" id="add">＋ &nbsp; Add a task</button></main></div><div class="mobile-nav"><span>◷<br><b>My day</b></span><span>▣<br>Upcoming</span><span>＋<br>Add task</span><span>⌑<br>Done</span></div></div><script>document.getElementById('date').textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'});document.querySelectorAll('.check').forEach(c=>c.onclick=()=>{c.parentElement.classList.toggle('done')});document.getElementById('add').onclick=()=>{const title=prompt('What would you like to get done?');if(title){const row=document.createElement('div');row.className='task';row.innerHTML='<div class="check"></div><div class="taskcopy"><b></b><small>◷ &nbsp; Today · Personal</small></div>';row.querySelector('b').textContent=title;row.querySelector('.check').onclick=()=>row.classList.toggle('done');document.getElementById('tasks').append(row)}};</script></body></html>
HTML

printf '%s\n' "Serving $OUTPUT_DIR/site on port $PORT"
exec /usr/bin/time -p node -e 'const http=require("http"),fs=require("fs"),path=require("path");const root=process.argv[1];const types={".html":"text/html",".css":"text/css",".js":"application/javascript"};http.createServer((req,res)=>{let p=path.join(root,decodeURIComponent(new URL(req.url,"http://localhost").pathname));if(!p.startsWith(root)){res.writeHead(403).end();return}try{if(fs.statSync(p).isDirectory())p=path.join(p,"index.html");res.setHeader("Content-Type",types[path.extname(p)]||"application/octet-stream");res.end(fs.readFileSync(p))}catch{res.writeHead(404).end("Not found")}}).listen(Number(process.env.PORT||3000),"0.0.0.0")' "$OUTPUT_DIR/site"
